    if (!r || !b || r[0] !== b.min || r[1] !== b.max) throw new Error(`harness: the ruled sepal load bound for ${id} (${r && r.join('..')}) and the geometry's SEPAL_TWIN_BOUNDS (${b && `${b.min}..${b.max}`}) disagree`);
