    for (const [name, o] of Object.entries(organs)) if (o.panels || o.displaced || !(o.refused && o.refused.infill === o.blades)) bad.push(`TX6: ${name}: ${o.blades} blades, ${o.refused && o.refused.infill || 0} refused for the infill, ${o.panels} panels textured, ${o.displaced} vertices displaced — under the infill every blade is refused and nothing moves`);
    if (!/TEXTURE NOT BUILT/.test(readout) || !/infill/i.test(readout)) bad.push('TX6: the read-out does not say the texture was NOT BUILT because of the infill');
    return bad;
