    if (Math.abs(wl - 1) > 1e-9) { bad.push(`TX5: ${name}: an apex direction of length ${wl}`); break; }
    if (!(q.s >= 0 && q.s <= C.H + 1e-9)) { bad.push(`TX5: ${name}: an apex relieved by ${q.s} mm against [0, ${C.H}]`); break; }
    const dd = Math.sqrt((q.r[0] - q.o[0] - q.s * q.w[0]) ** 2 + (q.r[1] - q.o[1] - q.s * q.w[1]) ** 2 + (q.r[2] - q.o[2] - q.s * q.w[2]) ** 2);
    if (dd > 1e-9) { bad.push(`TX5: ${name}: the relieved apex is ${dd.toExponential(2)} mm off the original apex moved ${q.s} mm along its own w — the bead is not relieved ALONG itself`); break; }
