      if (!(N[0] === 0 && N[1] === 0 && N[2] === 1)) bad.push(`JS1: stamen ${i}'s normal ${JSON.stringify(N)} is not exactly the hub plane's [0,0,1]`);
      if (s.root[2] !== 0) bad.push(`JS1: stamen ${i}'s root z = ${s.root[2]}, not exactly 0 — it left the hub plane`);
