      const C = which === 0 ? s.inner : s.outer;
      if (!Array.isArray(ring) || ring.length !== STAMEN_SIDES) { bad.push(`JS3: stamen ${i}'s ${which === 0 ? 'inner' : 'outer'} root ring has ${ring && ring.length} points, expected ${STAMEN_SIDES}`); return; }
