    if (inert || !(hubR > outerR) || !(denom > 0)) return inert ? hubT : joinT;
    const rr = Math.min(hubR, Math.max(outerR, r));
    return Math.max(hubT, joinT * Math.sqrt(Math.log(hubR / rr) / denom));
