      bad.push(`ST1: the builder emitted ${m.stemTris} triangles for ${shape}${cutMade ? ' ending on a florist\'s cut' : ''} of ${bands} band(s) on ${N} sides; the plan's own station list and side count ask for ${wantTris}`);
