  if (K.widthForced !== E.widthForced) bad.push(`UM1: the builder says the width ${K.widthForced ? 'was' : 'was not'} forced; restated it ${E.widthForced ? 'is' : 'is not'} (asked ${(1 + E.kAsked).toFixed(3)}x, held ${(1 + E.k).toFixed(3)}x)`);
