  if (!unitState || unitState.inflorescence !== 'UMBEL' || String(unitState.umbelDepth) !== '1' || Number(unitState.umbelLevel) !== 2 || String(unitState.umbelHead) !== 'OFF') bad.push(`UM5: a ray was built with ${unitState ? `inflorescence ${unitState.inflorescence}, depth ${unitState.umbelDepth}, level ${unitState.umbelLevel}, head ${unitState.umbelHead}` : 'no state'} — a ray carries a HEADLESS depth-1 sub-umbel at level 2`);
  if (!sub.floretState || sub.floretState.inflorescence !== 'NONE') bad.push(`UM5: the sub-umbel's florets were built with inflorescence ${sub.floretState && sub.floretState.inflorescence} — a floret of a sub-umbel is a flower: THE PIN IS LIFTED ONE LEVEL, NOT TWO`);
