/* The pre-spread, pre-centre matrix, frozen. tools/diff-bloom-bytes.mjs runs
   exactly these rows on both trees so the byte comparison is like-for-like:
   the new controls sit at their defaults and every one of these rows must
   come back bit-identical. Frozen means frozen — it is a record of what the
   scaffold's matrix was at 37e160d, not a view over the live registry, so it
   must never be rewritten to track a registry change. Note that its rows PIN
   only the four original sliders, so they inherit every later default — a
   deliberate change to one (e.g. the spread default) moves them all, by
   design. See diff-bloom-bytes.mjs's header on why that is not a regression. */
export function legacyMatrix() {
  const ids = ['petalCount', 'petalLength', 'petalWidth', 'petalTilt'];
  const byId = Object.fromEntries(CONTROLS.map((c) => [c.id, c]));
  const rows = [{ label: 'DEFAULT (the shipping configuration)', set: [] }];
  for (let n = 3; n <= 40; n++) rows.push({ label: `petalCount ${n}`, set: [{ id: 'petalCount', value: String(n) }] });
  for (const id of ids.slice(1)) {
    rows.push({ label: `${id} min (${byId[id].min})`, set: [{ id, value: String(byId[id].min) }] });
    rows.push({ label: `${id} max (${byId[id].max})`, set: [{ id, value: String(byId[id].max) }] });
  }
  rows.push({ label: 'ALL MIN (fewest, smallest, flat)', set: ids.map((id) => ({ id, value: String(byId[id].min) })) });
  rows.push({ label: 'ALL MAX (most petals, largest, steepest tilt)', set: ids.map((id) => ({ id, value: String(byId[id].max) })) });
  return rows;
}

/* ===================================================================
   phase10Matrix() — THE 376 ROWS AS THEY STOOD AT 4f39118, frozen.

   The like-for-like baseline for EVA'S RULING OF SEP 3 FROM THE DEPLOY
   PREVIEW — the all-petals group at one whorl, and Petal 1 / Petal N hidden
   and INERT there (the one-whorl orchid retired). Frozen at the last commit
   before that change, so the byte report can say which of these rows moved
   and prove it is exactly the predicted set.

   AND IT IS ONE OF THREE BASELINES THIS SESSION PREDICTED TO MOVE, on a NAMED
   partition: the 33 rows with a labellum or hood control engaged at ONE WHORL
   on RADIAL — enumerated by a script over every matrix before a byte was
   hashed, and found in exactly phase8, phase9 and this one (legacy and
   phase2–phase7 carry none). MEASURED: 30 of the 33 moved and 3 did not, on
   all three matrices identically, and nothing outside the 33 moved. The three
   are rows whose override CLAMPS TO THE BASE'S OWN VALUE (size x2.00 on a
   60 mm petal, tip 0.6 + 0.6, curl -180 + -180) — already bit-identical to
   their no-override counterparts on the base tree, so the retirement had
   nothing to move there. All 33 are bit-identical to their counterparts on
   the new tree. Eva ruled thirty the honest set; the charter's session-11
   entry carries the measurement and the footnote on the predicate.

   GENERATED FROM 4f39118's OWN buildMatrix() rather than transcribed, and
   `--verify-frozen --phase10` proves it deep-equal to that commit's output in
   CI on every push. */
